 315 |   <body>
 316 |     <div id="toolbar">
 317 |       <button id="btn-table" disabled>🪑 Place Table <span class="hint">[T]</span></button>
 318 |       <button id="btn-couch">🛋️ Sofa <span class="hint">[C]</span></button>
 319 |       <button id="btn-lsofa">📐 L-Sofa <span class="hint">[L]</span></button>
 320 |       <button id="btn-chair">🪑 Chair <span class="hint">[H]</span></button>
 321 |       <button id="btn-rug">🟫 Rug <span class="hint">[P]</span></button>
 322 |       <button id="btn-punch" title="Select a rect inside a table, then press U to punch a hole" style="cursor:default;opacity:0.75">🍩 Punch <span class="hint">[U]</span></button>
 323 |       <button id="btn-edit"   disabled>✏️ Edit <span class="hint">[E]</span></button>
 324 |       <button id="btn-delete" disabled>🗑️ Delete <span class="hint">[D]</span></button>
 325 |     </div>
 326 |     <div id="board-wrap">
 327 |       <div id="board"></div>
 328 |       <div id="overlay"></div>
 329 |       <div id="selection-overlay"></div>
 330 |       <div id="couch-ghost"></div>
 331 |       <div id="chair-ghost"></div>
 332 |       <div id="lsofa-ghost"><canvas id="lsofa-ghost-canvas"></canvas></div>
 333 |     </div>
 334 |     <div id="rug-counter">0 / 16 cells — Enter to place, Esc to cancel</div>
