 337 |     <script>
 338 |       const CELL = 12, SIZE = 64;
 339 |       const board     = document.getElementById("board");
 340 |       const overlay   = document.getElementById("overlay");
 341 |       const selOverlay = document.getElementById("selection-overlay");
 342 |       const btnTable  = document.getElementById("btn-table");
 343 |       const btnCouch  = document.getElementById("btn-couch");
 344 |       const btnLsofa  = document.getElementById("btn-lsofa");
 345 |       const btnChair  = document.getElementById("btn-chair");
 346 |       const btnRug    = document.getElementById("btn-rug");
 347 |       const btnEdit   = document.getElementById("btn-edit");
 348 |       const btnDelete = document.getElementById("btn-delete");
 349 |       const boardWrap = document.getElementById("board-wrap");
 350 |       const couchGhostEl = document.getElementById("couch-ghost");
 351 |       const chairGhostEl = document.getElementById("chair-ghost");
 352 |       const lsofaGhostEl = document.getElementById("lsofa-ghost");
 353 |       const lsofaGhostCanvas = document.getElementById("lsofa-ghost-canvas");
 354 |       const rugCounterEl = document.getElementById("rug-counter");
 355 | 
 356 |       const TABLE_COLORS = [
 357 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
 358 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
 359 |       ];
 360 | 
 361 |       // ── State ────────────────────────────────────────────────────────────────
 362 |       let tableCount = 0;
 363 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
 364 |       const tableGrid = [];   // tableGrid[row][col] = array of piece ids occupying that cell
 365 |       let selectedTable = null;   // table currently clicked/focused
 366 |       let editingTable  = null;   // table lifted into edit mode
 367 | 
 368 |       let couchCount = 0;
 369 |       let couchMode  = false;     // true while couch-placement is active
 370 |       let ghostOrientation = "h"; // "h" or "v" — orientation of the next couch to be placed
 371 | 
 372 |       let chairCount = 0;
 373 |       let chairMode  = false;
 374 | 
 375 |       let lsofaCount = 0;
 376 |       let lsofaMode  = false;
 377 |       // Variants: "se" "sw" "ne" "nw" — which direction the two arms extend from the corner
 378 |       let lsofaVariant = "se";
 379 |       // Ghost arm lengths (editable via handles during placement ghost drag)
 380 |       let lsofaGhostLenA = 3; // horizontal arm (min 2)
 381 |       let lsofaGhostLenB = 3; // vertical arm   (min 2)
 382 | 
 383 |       let rugCount = 0;
 384 |       let rugMode  = false;
 385 |       const RUG_MAX_CELLS = 16;
 386 |       let rugPaintCells = new Set();
 387 | 
 388 |       let donutCount = 0;
 389 |       const DONUT_MIN_ROWS = 3, DONUT_MIN_COLS = 3;
 390 |       const DONUT_MAX_ROWS = 16, DONUT_MAX_COLS = 24;
 391 | 
 392 |       // ── Build cell grid ──────────────────────────────────────────────────────
 393 |       const cells = [];
 394 |       for (let row = 0; row < SIZE; row++) {
 395 |         cells[row] = []; tableGrid[row] = [];
 396 |         for (let col = 0; col < SIZE; col++) {
 397 |           const cell = document.createElement("div");
 398 |           cell.classList.add("cell");
 399 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
 400 |           cell.dataset.row = row; cell.dataset.col = col;
 401 |           cells[row][col] = cell; tableGrid[row][col] = [];
 402 |           board.appendChild(cell);
 403 |         }
 404 |       }
 405 | 
 406 |       // ── Selection helpers ────────────────────────────────────────────────────
 407 |       let selection = null;
 408 |       let isSelecting = false, selStartRow = null, selStartCol = null;
 409 | 
 410 |       function clearClass(cls) {
 411 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
 412 |       }
 413 |       function paintRect(r1,c1,r2,c2,cls) {
 414 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
 415 |       }
 416 |       function renderSelection() {
 417 |         clearClass("selected");
 418 |         if (selection) {
 419 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
 420 |           selOverlay.style.left    = (selection.cMin * CELL) + "px";
 421 |           selOverlay.style.top     = (selection.rMin * CELL) + "px";
 422 |           selOverlay.style.width   = ((selection.cMax - selection.cMin + 1) * CELL) + "px";
 423 |           selOverlay.style.height  = ((selection.rMax - selection.rMin + 1) * CELL) + "px";
 424 |           selOverlay.style.display = "block";
 425 |         } else {
 426 |           selOverlay.style.display = "none";
 427 |         }
 428 |         btnTable.disabled = !selection;
 429 |         btnEdit.disabled  = !selectedTable;
 430 |       }
 431 |       function selPreviewRect(curRow,curCol) {
 432 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
 433 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
 434 |         let raw;
 435 |         if (!selection) raw = {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
 436 |         else raw = {
 437 |           rMin:Math.min(selection.rMin,dr1), cMin:Math.min(selection.cMin,dc1),
 438 |           rMax:Math.max(selection.rMax,dr2), cMax:Math.max(selection.cMax,dc2),
 439 |         };
 440 |         const { rMin, cMin, rMax, cMax } = raw;
 441 |         return clampTableSelection(rMin, cMin, rMax, cMax);
 442 |       }
 443 |       function applySelPreview(curRow,curCol) {
 444 |         clearClass("preview");
 445 |         clearClass("conflict");
 446 |         clearClass("punch-preview");
 447 |         clearClass("punch-conflict");
 448 |         const r = selPreviewRect(curRow,curCol);
 449 |         const punchTarget = getPunchTarget(r);
 450 |         if (punchTarget) {
 451 |           // All cells in selection get punch-preview colour
 452 |           for (let row=r.rMin;row<=r.rMax;row++)
 453 |             for (let col=r.cMin;col<=r.cMax;col++)
 454 |               cells[row][col].classList.add("punch-preview");
 455 |         } else {
 456 |           for (let row=r.rMin;row<=r.rMax;row++) {
 457 |             for (let col=r.cMin;col<=r.cMax;col++) {
 458 |               if (tableGrid[row][col].length > 0) {
 459 |                 cells[row][col].classList.add("conflict");
 460 |               } else {
 461 |                 cells[row][col].classList.add("preview");
 462 |               }
 463 |             }
 464 |           }
 465 |         }
 466 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
 467 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
 468 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
 469 |         selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
 470 |         selOverlay.style.display = "block";
 471 |       }
 472 | 
 473 |       /**
 474 |        * If `sel` is a valid punch rect (completely inside exactly one plain table
 475 |        * with ≥1 cell margin on all sides), return that table. Otherwise null.
 476 |        */
 477 |       function getPunchTarget(sel) {
 478 |         // Must leave at least 1-cell border → outer must be at least 3×3
 479 |         const outerRMin = sel.rMin - 1, outerCMin = sel.cMin - 1;
 480 |         const outerRMax = sel.rMax + 1, outerCMax = sel.cMax + 1;
 481 |         if (outerRMin < 0 || outerCMin < 0 || outerRMax >= SIZE || outerCMax >= SIZE) return null;
 482 |         // Every cell in the selection must belong to the same single table (type:"table")
 483 |         let target = null;
 484 |         for (let r=sel.rMin; r<=sel.rMax; r++) {
 485 |           for (let c=sel.cMin; c<=sel.cMax; c++) {
 486 |             const ids = tableGrid[r][c].filter(id => {
 487 |               const p = tables.find(t => t.id === id);
 488 |               return p && p.type === "table";
 489 |             });
 490 |             if (ids.length !== 1) return null;
 491 |             const piece = tables.find(t => t.id === ids[0]);
 492 |             if (!target) target = piece;
 493 |             else if (target !== piece) return null;
 494 |           }
 495 |         }
 496 |         if (!target) return null;
 497 |         // The outer ring cells must all also belong to the same target
 498 |         // (ensures the hole is truly interior, not on the edge of the table)
 499 |         if (target.rMin > outerRMin || target.cMin > outerCMin ||
 500 |             target.rMax < outerRMax || target.cMax < outerCMax) return null;
 501 |         return target;
 502 |       }
 503 | 
 504 | 
 505 |       // ── Cell colour helpers ──────────────────────────────────────────────────
 506 |       function resetCell(r,c) {
 507 |         const cell = cells[r][c];
 508 |         cell.style.backgroundColor = "";
 509 |         cell.style.opacity = "";
 510 |         cell.classList.remove("selected","preview");
 511 |         cell.classList.add((r+c)%2===0 ? "light" : "dark");
 512 |         tableGrid[r][c] = [];
 513 |       }
 514 |       function stampTable(t) {
 515 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
 516 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
 517 |           if (t.type === "chair") refreshChairBadge(r, c);
 518 |         }
 519 |       }
 520 |       function eraseTable(t) {
