 609 |       // ── Conflict detection ───────────────────────────────────────────────────
 610 |       // Returns true if the given rect overlaps any piece (optionally ignoring one id).
 611 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
 612 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
 613 |           for (const tid of tableGrid[r][c]) {
 614 |             if (tid !== ignoreId) return true;
 615 |           }
 616 |         }
 617 |         return false;
 618 |       }
