 620 |       // Chair-specific conflict: only blocks on non-chair pieces (chairs can stack).
 621 |       function hasConflictForChair(row, col, ignoreId=null) {
 622 |         for (const tid of tableGrid[row][col]) {
 623 |           if (tid === ignoreId) continue;
 624 |           const piece = tables.find(t => t.id === tid);
 625 |           if (piece && piece.type !== "chair") return true;
 626 |         }
 627 |         return false;
 628 |       }
