 630 |       // Couch-specific conflict: blocks on any other piece — couches cannot stack.
 631 |       function hasConflictForCouch(rMin, cMin, rMax, cMax, ignoreId=null) {
 632 |         return hasConflict(rMin, cMin, rMax, cMax, ignoreId);
 633 |       }
