 635 |       // ── Place Table ──────────────────────────────────────────────────────────
 636 |       const TABLE_MIN_ROWS = 2, TABLE_MIN_COLS = 3;
 637 |       const TABLE_MAX_ROWS = 16, TABLE_MAX_COLS = 24;
 638 | 
 639 |       /** Enforce table size limits on a raw selection rect. Returns clamped rect. */
 640 |       function clampTableSelection(rMin, cMin, rMax, cMax) {
 641 |         const rows = rMax - rMin + 1, cols = cMax - cMin + 1;
 642 |         // Enforce minimum
 643 |         const r2 = Math.min(rMin + Math.max(rows, TABLE_MIN_ROWS) - 1, SIZE - 1);
 644 |         const c2 = Math.min(cMin + Math.max(cols, TABLE_MIN_COLS) - 1, SIZE - 1);
 645 |         // Enforce maximum
 646 |         const r3 = Math.min(r2, rMin + TABLE_MAX_ROWS - 1);
 647 |         const c3 = Math.min(c2, cMin + TABLE_MAX_COLS - 1);
 648 |         return { rMin, cMin, rMax: r3, cMax: c3 };
 649 |       }
 650 | 
 651 |       /**
 652 |        * Fracture any type:"table" pieces whose footprint overlaps the given rect.
 653 |        * The overlapping table is deleted and replaced by up to 4 non-overlapping
 654 |        * rectangular shards (top / bottom / left strip / right strip) using a
 655 |        * guillotine cut around the intersection.
 656 |        * Call this AFTER the new piece has been stamped so tableGrid is current.
 657 |        * Pass the new piece's id as `ignoreId` so we don't fracture the piece itself.
 658 |        */
 659 |       function fractureTablesUnder(nR1, nC1, nR2, nC2, ignoreId) {
 660 |         // Collect every table-type piece whose cells overlap the new rect
 661 |         const victims = new Set();
 662 |         for (let r = nR1; r <= nR2; r++) {
 663 |           for (let c = nC1; c <= nC2; c++) {
 664 |             for (const tid of tableGrid[r][c]) {
 665 |               if (tid === ignoreId) continue;
 666 |               const p = tables.find(t => t.id === tid);
 667 |               if (p && p.type === "table") victims.add(p);
 668 |             }
 669 |           }
 670 |         }
 671 |         for (const victim of victims) {
 672 |           // Intersection of victim with the new rect
 673 |           const oR1 = Math.max(victim.rMin, nR1), oC1 = Math.max(victim.cMin, nC1);
 674 |           const oR2 = Math.min(victim.rMax, nR2), oC2 = Math.min(victim.cMax, nC2);
 675 |           if (oR1 > oR2 || oC1 > oC2) continue; // no actual overlap (shouldn't happen)
 676 | 
 677 |           // Remember bounds before deletion
 678 |           const vR1 = victim.rMin, vC1 = victim.cMin;
 679 |           const vR2 = victim.rMax, vC2 = victim.cMax;
 680 |           const vColor = victim.color;
 681 | 
 682 |           deleteTable(victim);
 683 | 
 684 |           // Up to 4 shards — each only created if non-empty
 685 |           const shards = [
 686 |             { rMin: vR1,    cMin: vC1,    rMax: oR1-1, cMax: vC2    }, // top
 687 |             { rMin: oR2+1,  cMin: vC1,    rMax: vR2,   cMax: vC2    }, // bottom
 688 |             { rMin: oR1,    cMin: vC1,    rMax: oR2,   cMax: oC1-1  }, // left
 689 |             { rMin: oR1,    cMin: oC2+1,  rMax: oR2,   cMax: vC2    }, // right
 690 |           ];
 691 |           for (const s of shards) {
 692 |             if (s.rMin > s.rMax || s.cMin > s.cMax) continue; // empty shard
 693 |             spawnTable(s.rMin, s.cMin, s.rMax, s.cMax, vColor);
 694 |           }
 695 |         }
 696 |       }
