 807 |       function updateCouchGhost(row, col) {
 808 |         const { rows, cols } = couchDims(ghostOrientation);
 809 |         // Clamp so the ghost stays on board
 810 |         const rMin = Math.max(0, Math.min(row, SIZE - rows));
 811 |         const cMin = Math.max(0, Math.min(col, SIZE - cols));
 812 |         couchGhostEl.style.left    = (cMin * CELL) + "px";
 813 |         couchGhostEl.style.top     = (rMin * CELL) + "px";
 814 |         couchGhostEl.style.width   = (cols * CELL) + "px";
 815 |         couchGhostEl.style.height  = (rows * CELL) + "px";
 816 |         couchGhostEl.style.display = "block";
 817 |         const conflict = hasConflictForCouch(rMin, cMin, rMin + rows - 1, cMin + cols - 1);
 818 |         couchGhostEl.classList.toggle("conflict", conflict);
 819 |       }
