 823 |         const rMin = Math.max(0, Math.min(row, SIZE - rows));
 824 |         const cMin = Math.max(0, Math.min(col, SIZE - cols));
 825 |         const rMax = rMin + rows - 1;
 826 |         const cMax = cMin + cols - 1;
 827 |         if (hasConflictForCouch(rMin, cMin, rMax, cMax)) {/* visual-only: allow placement */}
