 829 |         const color = COUCH_COLORS[couchCount % COUCH_COLORS.length];
 830 |         const id    = tableCount++; // share global id counter so drag logic works uniformly
 831 |         couchCount++;
 832 |         const label = `Couch ${couchCount}`;
