 876 |       // ── Rotation dispatcher ──────────────────────────────────────────────────
 877 |       // R key: rotates the selected piece (or toggles ghost orientation in placement modes).
 878 |       function handleRotate() {
 879 |         // L-sofa mode or selected L-sofa
 880 |         if (lsofaMode || (selectedTable && selectedTable.type === "lsofa")) {
 881 |           handleLsofaRotate(); return;
 882 |         }
 883 |         // Couch placement ghost
 884 |         if (couchMode) {
 885 |           ghostOrientation = ghostOrientation === "h" ? "v" : "h";
 886 |           couchGhostEl.style.display = "none";
 887 |           return;
 888 |         }
 889 |         if (!selectedTable) return;
 890 |         if (selectedTable.type === "couch")  { rotateCouch(selectedTable);  return; }
 891 |         if (selectedTable.type === "table")  { rotateTable(selectedTable);  return; }
 892 |         if (selectedTable.type === "rug")    { rotateRug(selectedTable);    return; }
 893 |         if (selectedTable.type === "donut")  { rotateDonut(selectedTable);  return; }
 894 |         // chair is 1×1 — no rotation needed
 895 |       }
