 897 |       function rotateCouch(t) {
 898 |         const newOrientation = t.orientation === "h" ? "v" : "h";
 899 |         // Pivot around top-left corner: swap (rMax-rMin) ↔ (cMax-cMin)
 900 |         const height = t.rMax - t.rMin; // current row-span minus 1
 901 |         const width  = t.cMax - t.cMin; // current col-span minus 1
 902 |         const newRMax = t.rMin + width;
 903 |         const newCMax = t.cMin + height;
 904 |         // Clamp to board
 905 |         const rMax = Math.min(newRMax, SIZE - 1);
 906 |         const cMax = Math.min(newCMax, SIZE - 1);
 907 |         const rMin = t.rMin;
 908 |         const cMin = t.cMin;
 909 |         // Check for conflicts (ignoring self) — visual only for rotation
 910 |         eraseTable(t);
 911 |         t.rMax = rMax;
 912 |         t.cMax = cMax;
 913 |         t.orientation = newOrientation;
 914 |         stampTable(t);
 915 |         positionEl(t);
 916 |         applyHandleClasses(t);
 917 |       }
