 919 |       /** Rotate a plain rectangular table 90° CW around its top-left corner. */
 920 |       function rotateTable(t) {
 921 |         const h = t.rMax - t.rMin; // span in rows (0-based delta)
 922 |         const w = t.cMax - t.cMin; // span in cols (0-based delta)
 923 |         // After CW rotation, rows←cols and cols←rows
 924 |         const newRowSpan = w, newColSpan = h; // 0-based deltas
 925 |         const newRows = newRowSpan + 1, newCols = newColSpan + 1;
 926 |         // Enforce min/max bounds — skip rotation if it would violate them
 927 |         if (newRows < TABLE_MIN_ROWS || newCols < TABLE_MIN_COLS) return;
 928 |         if (newRows > TABLE_MAX_ROWS || newCols > TABLE_MAX_COLS) return;
 929 |         const newRMax = Math.min(t.rMin + newRowSpan, SIZE - 1);
 930 |         const newCMax = Math.min(t.cMin + newColSpan, SIZE - 1);
 931 |         eraseTable(t);
 932 |         t.rMax = newRMax;
 933 |         t.cMax = newCMax;
 934 |         stampTable(t);
 935 |         positionEl(t);
 936 |       }
