 938 |       /** Rotate a rug's cells 90° CW, keeping bounding-box top-left fixed. */
 939 |       function rotateRug(t) {
 940 |         const H = t.rMax - t.rMin + 1; // current bbox height
 941 |         // 90° CW around top-left: (dr, dc) → (dc, H-1-dr)
 942 |         const rotated = t.cells.map(({r, c}) => {
 943 |           const dr = r - t.rMin, dc = c - t.cMin;
 944 |           return { r: t.rMin + dc, c: t.cMin + (H - 1 - dr) };
 945 |         });
 946 |         // Clamp so we stay on the board
 947 |         const bb = rugBBox(rotated);
 948 |         const dr = Math.max(0, -bb.rMin) + Math.min(0, SIZE - 1 - bb.rMax);
 949 |         const dc = Math.max(0, -bb.cMin) + Math.min(0, SIZE - 1 - bb.cMax);
 950 |         const clamped = rotated.map(({r, c}) => ({ r: r + dr, c: c + dc }));
 951 |         eraseRug(t);
 952 |         t.cells = clamped;
 953 |         stampRug(t);
 954 |         renderRugEl(t);
 955 |       }
