 987 |       // Returns true if (row,col) is orthogonally adjacent to a table cell.
 988 |       function isAdjacentToTable(row, col) {
 989 |         const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
 990 |         for (const [dr, dc] of dirs) {
 991 |           const r = row + dr, c = col + dc;
 992 |           if (r < 0 || r >= SIZE || c < 0 || c >= SIZE) continue;
 993 |           for (const id of tableGrid[r][c]) {
 994 |             const piece = tables.find(t => t.id === id);
