1650 |       /** BFS connectivity check — returns true if all cells in cellSet are connected. */
1651 |       function rugIsConnected(cellSet) {
1652 |         if (cellSet.size <= 1) return true;
1653 |         const arr = [...cellSet];
1654 |         const visited = new Set();
1655 |         const queue = [arr[0]];
1656 |         visited.add(arr[0]);
1657 |         while (queue.length) {
1658 |           const key = queue.shift();
1659 |           const [r,c] = key.split(",").map(Number);
1660 |           for (const [dr,dc] of [[-1,0],[1,0],[0,-1],[0,1]]) {
1661 |             const nk = `${r+dr},${c+dc}`;
1662 |             if (cellSet.has(nk) && !visited.has(nk)) { visited.add(nk); queue.push(nk); }
1663 |           }
1664 |         }
1665 |         return visited.size === cellSet.size;
1666 |       }
