  // ── Chaos mode ──────────────────────────────────────────────────────────
  // Randomly teleports all furniture pieces at a fixed interval.

  const btnChaos = document.getElementById("btn-chaos");
  let chaosMode     = false;
  let chaosInterval = null;
  const CHAOS_INTERVAL_MS = 1200; // ms between teleport waves
  const TELEPORT_MAX_TRIES = 300; // max random attempts per piece

  /**
   * Teleport a single piece to a random valid position on the board.
   * Returns true if a valid position was found and the piece was moved.
   */
  function teleportPiece(t) {
    for (let attempt = 0; attempt < TELEPORT_MAX_TRIES; attempt++) {
      const r = Math.floor(Math.random() * SIZE);
      const c = Math.floor(Math.random() * SIZE);

      if (t.type === "lsofa") {
        // Keep lenA, lenB, variant — just pick new corner position
        if (hasConflictL(r, c, t.lenA, t.lenB, t.variant, t.id)) continue;
        eraseLsofa(t);
        t.cornerR = r; t.cornerC = c;
        stampLsofa(t);
        renderLsofaEl(t);
        return true;

      } else if (t.type === "rug") {
        const newCells = rugOffsetCells(t, r, c);
        if (hasConflictForRug(newCells, t.id)) continue;
        eraseRug(t);
        const dr = r - t.rMin, dc = c - t.cMin;
        t.cells = t.cells.map(({r: cr, c: cc}) => ({ r: cr + dr, c: cc + dc }));
        const bb = rugBBox(t.cells);
        t.rMin = bb.rMin; t.rMax = bb.rMax; t.cMin = bb.cMin; t.cMax = bb.cMax;
        stampRug(t);
        renderRugEl(t);
        return true;

      } else if (t.type === "donut") {
        const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
        const newRMax = r + h, newCMax = c + w;
        if (newRMax >= SIZE || newCMax >= SIZE) continue;
        const dr = r - t.rMin, dc = c - t.cMin;
        const newHole = {
          rMin: t.hole.rMin + dr, cMin: t.hole.cMin + dc,
          rMax: t.hole.rMax + dr, cMax: t.hole.cMax + dc,
        };
        const movedT = { ...t, rMin: r, cMin: c, rMax: newRMax, cMax: newCMax, hole: newHole };
        if (hasConflictForDonut(movedT, t.id)) continue;
        eraseDonut(t);
        t.hole = newHole;
        t.rMin = r; t.cMin = c; t.rMax = newRMax; t.cMax = newCMax;
        stampDonut(t);
        renderDonutEl(t);
        return true;

      } else if (t.type === "chair") {
        if (hasConflictForChair(r, c, t.id)) continue;
        eraseTable(t);
        t.rMin = r; t.cMin = c; t.rMax = r; t.cMax = c;
        stampTable(t);
        positionEl(t);
        refreshChairBadge(r, c);
        return true;

      } else if (t.type === "couch") {
        const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
        const newRMax = r + h, newCMax = c + w;
        if (newRMax >= SIZE || newCMax >= SIZE) continue;
        if (hasConflictForCouch(r, c, newRMax, newCMax, t.id)) continue;
        eraseTable(t);
        t.rMin = r; t.cMin = c; t.rMax = newRMax; t.cMax = newCMax;
        stampTable(t);
        positionEl(t);
        return true;

      } else {
        // plain "table" (rectangular)
        const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
        const newRMax = r + h, newCMax = c + w;
        if (newRMax >= SIZE || newCMax >= SIZE) continue;
        if (hasConflict(r, c, newRMax, newCMax, t.id)) continue;
        eraseTable(t);
        t.rMin = r; t.cMin = c; t.rMax = newRMax; t.cMax = newCMax;
        stampTable(t);
        positionEl(t);
        return true;
      }
    }
    return false; // couldn't find a free spot — leave piece in place
  }

  /** Flash the teleport animation on a piece's element. */
  function flashTeleport(el) {
    el.classList.remove("teleporting");
    // Force reflow to restart the animation if already running
    void el.offsetWidth;
    el.classList.add("teleporting");
    el.addEventListener("animationend", () => el.classList.remove("teleporting"), { once: true });
  }

  /** Teleport every piece on the board to a random position. */
  function randomTeleportAll() {
    // Shuffle the order so we don't always favour the first-placed pieces
    const shuffled = [...tables].sort(() => Math.random() - 0.5);
    for (const t of shuffled) {
      if (t === movingTable) continue; // don't teleport something the user is dragging
      const moved = teleportPiece(t);
      if (moved) flashTeleport(t.el);
    }
  }

  function toggleChaosMode() {
    chaosMode = !chaosMode;
    if (chaosMode) {
      btnChaos.classList.add("chaos-active");
      randomTeleportAll();                            // fire immediately on enable
      chaosInterval = setInterval(randomTeleportAll, CHAOS_INTERVAL_MS);
    } else {
      btnChaos.classList.remove("chaos-active");
      clearInterval(chaosInterval);
      chaosInterval = null;
    }
  }

  btnChaos.addEventListener("click", toggleChaosMode);
</script>

