633 |       // ── Conflict detection ───────────────────────────────────────────────────
634 |       // Returns true if the given rect overlaps any piece (optionally ignoring one id).
635 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
636 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
637 |           for (const tid of tableGrid[r][c]) {
638 |             if (tid !== ignoreId) return true;
639 |           }
640 |         }
641 |         return false;
642 |       }
