644 |       // Chair-specific conflict: only blocks on non-chair pieces (chairs can stack).
645 |       function hasConflictForChair(row, col, ignoreId=null) {
646 |         for (const tid of tableGrid[row][col]) {
647 |           if (tid === ignoreId) continue;
648 |           const piece = tables.find(t => t.id === tid);
649 |           if (piece && piece.type !== "chair") return true;
650 |         }
651 |         return false;
652 |       }
653 | 
654 |       // Couch-specific conflict: blocks on any other piece — couches cannot stack.
655 |       function hasConflictForCouch(rMin, cMin, rMax, cMax, ignoreId=null) {
656 |         return hasConflict(rMin, cMin, rMax, cMax, ignoreId);
657 |       }
