663 |       /** Enforce table size limits on a raw selection rect. Returns clamped rect. */
664 |       function clampTableSelection(rMin, cMin, rMax, cMax) {
665 |         const rows = rMax - rMin + 1, cols = cMax - cMin + 1;
666 |         // Enforce minimum
667 |         const r2 = Math.min(rMin + Math.max(rows, TABLE_MIN_ROWS) - 1, SIZE - 1);
668 |         const c2 = Math.min(cMin + Math.max(cols, TABLE_MIN_COLS) - 1, SIZE - 1);
669 |         // Enforce maximum
670 |         const r3 = Math.min(r2, rMin + TABLE_MAX_ROWS - 1);
671 |         const c3 = Math.min(c2, cMin + TABLE_MAX_COLS - 1);
672 |         return { rMin, cMin, rMax: r3, cMax: c3 };
673 |       }
