675 |       /**
676 |        * Fracture any type:"table" pieces whose footprint overlaps the given rect.
677 |        * The overlapping table is deleted and replaced by up to 4 non-overlapping
678 |        * rectangular shards (top / bottom / left strip / right strip) using a
679 |        * guillotine cut around the intersection.
680 |        * Call this AFTER the new piece has been stamped so tableGrid is current.
681 |        * Pass the new piece's id as `ignoreId` so we don't fracture the piece itself.
682 |        */
683 |       function fractureTablesUnder(nR1, nC1, nR2, nC2, ignoreId) {
684 |         // Collect every table-type piece whose cells overlap the new rect
685 |         const victims = new Set();
686 |         for (let r = nR1; r <= nR2; r++) {
687 |           for (let c = nC1; c <= nC2; c++) {
688 |             for (const tid of tableGrid[r][c]) {
689 |               if (tid === ignoreId) continue;
690 |               const p = tables.find(t => t.id === tid);
691 |               if (p && p.type === "table") victims.add(p);
692 |             }
693 |           }
694 |         }
695 |         for (const victim of victims) {
696 |           // Intersection of victim with the new rect
697 |           const oR1 = Math.max(victim.rMin, nR1), oC1 = Math.max(victim.cMin, nC1);
698 |           const oR2 = Math.min(victim.rMax, nR2), oC2 = Math.min(victim.cMax, nC2);
699 |           if (oR1 > oR2 || oC1 > oC2) continue; // no actual overlap (shouldn't happen)
700 | 
701 |           // Remember bounds before deletion
702 |           const vR1 = victim.rMin, vC1 = victim.cMin;
703 |           const vR2 = victim.rMax, vC2 = victim.cMax;
704 |           const vColor = victim.color;
705 | 
706 |           deleteTable(victim);
707 | 
708 |           // Up to 4 shards — each only created if non-empty
709 |           const shards = [
710 |             { rMin: vR1,    cMin: vC1,    rMax: oR1-1, cMax: vC2    }, // top
711 |             { rMin: oR2+1,  cMin: vC1,    rMax: vR2,   cMax: vC2    }, // bottom
712 |             { rMin: oR1,    cMin: vC1,    rMax: oR2,   cMax: oC1-1  }, // left
713 |             { rMin: oR1,    cMin: oC2+1,  rMax: oR2,   cMax: vC2    }, // right
714 |           ];
