361 |     <script>
362 |       const CELL = 12, SIZE = 64;
363 |       const board     = document.getElementById("board");
364 |       const overlay   = document.getElementById("overlay");
365 |       const selOverlay = document.getElementById("selection-overlay");
366 |       const btnTable  = document.getElementById("btn-table");
367 |       const btnCouch  = document.getElementById("btn-couch");
368 |       const btnLsofa  = document.getElementById("btn-lsofa");
369 |       const btnChair  = document.getElementById("btn-chair");
370 |       const btnRug    = document.getElementById("btn-rug");
371 |       const btnEdit   = document.getElementById("btn-edit");
372 |       const btnDelete = document.getElementById("btn-delete");
373 |       const boardWrap = document.getElementById("board-wrap");
374 |       const couchGhostEl = document.getElementById("couch-ghost");
375 |       const chairGhostEl = document.getElementById("chair-ghost");
376 |       const lsofaGhostEl = document.getElementById("lsofa-ghost");
377 |       const lsofaGhostCanvas = document.getElementById("lsofa-ghost-canvas");
378 |       const rugCounterEl = document.getElementById("rug-counter");
379 | 
380 |       const TABLE_COLORS = [
381 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
382 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
383 |       ];
384 | 
385 |       // ── State ────────────────────────────────────────────────────────────────
386 |       let tableCount = 0;
387 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
388 |       const tableGrid = [];   // tableGrid[row][col] = array of piece ids occupying that cell
389 |       let selectedTable = null;   // table currently clicked/focused
390 |       let editingTable  = null;   // table lifted into edit mode
391 | 
392 |       let couchCount = 0;
393 |       let couchMode  = false;     // true while couch-placement is active
394 |       let ghostOrientation = "h"; // "h" or "v" — orientation of the next couch to be placed
395 | 
396 |       let chairCount = 0;
397 |       let chairMode  = false;
398 | 
399 |       let lsofaCount = 0;
400 |       let lsofaMode  = false;

400 |       let lsofaMode  = false;
401 |       // Variants: "se" "sw" "ne" "nw" — which direction the two arms extend from the corner
402 |       let lsofaVariant = "se";
403 |       // Ghost arm lengths (editable via handles during placement ghost drag)
404 |       let lsofaGhostLenA = 3; // horizontal arm (min 2)
405 |       let lsofaGhostLenB = 3; // vertical arm   (min 2)
406 | 
407 |       let rugCount = 0;
408 |       let rugMode  = false;
409 |       const RUG_MAX_CELLS = 16;
410 |       let rugPaintCells = new Set();
411 | 
412 |       let donutCount = 0;
413 |       const DONUT_MIN_ROWS = 3, DONUT_MIN_COLS = 3;
414 |       const DONUT_MAX_ROWS = 16, DONUT_MAX_COLS = 24;
415 | 
416 |       // ── Build cell grid ──────────────────────────────────────────────────────
417 |       const cells = [];
418 |       for (let row = 0; row < SIZE; row++) {
419 |         cells[row] = []; tableGrid[row] = [];
420 |         for (let col = 0; col < SIZE; col++) {
421 |           const cell = document.createElement("div");
422 |           cell.classList.add("cell");
423 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
424 |           cell.dataset.row = row; cell.dataset.col = col;
425 |           cells[row][col] = cell; tableGrid[row][col] = [];
426 |           board.appendChild(cell);
427 |         }
428 |       }
429 | 
430 |       // ── Selection helpers ────────────────────────────────────────────────────
431 |       let selection = null;
432 |       let isSelecting = false, selStartRow = null, selStartCol = null;
433 | 
434 |       function clearClass(cls) {
435 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
436 |       }
437 |       function paintRect(r1,c1,r2,c2,cls) {
438 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
439 |       }
440 |       function renderSelection() {
441 |         clearClass("selected");
442 |         if (selection) {
443 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
444 |           selOverlay.style.left    = (selection.cMin * CELL) + "px";
445 |           selOverlay.style.top     = (selection.rMin * CELL) + "px";
446 |           selOverlay.style.width   = ((selection.cMax - selection.cMin + 1) * CELL) + "px";
447 |           selOverlay.style.height  = ((selection.rMax - selection.rMin + 1) * CELL) + "px";
448 |           selOverlay.style.display = "block";
449 |         } else {
450 |           selOverlay.style.display = "none";
451 |         }
452 |         btnTable.disabled = !selection;
453 |         btnEdit.disabled  = !selectedTable;
454 |       }
455 |       function selPreviewRect(curRow,curCol) {
456 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
457 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
458 |         let raw;
459 |         if (!selection) raw = {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
460 |         else raw = {
461 |           rMin:Math.min(selection.rMin,dr1), cMin:Math.min(selection.cMin,dc1),
462 |           rMax:Math.max(selection.rMax,dr2), cMax:Math.max(selection.cMax,dc2),
463 |         };
464 |         const { rMin, cMin, rMax, cMax } = raw;
465 |         return clampTableSelection(rMin, cMin, rMax, cMax);
466 |       }
467 |       function applySelPreview(curRow,curCol) {
468 |         clearClass("preview");
469 |         clearClass("conflict");
470 |         clearClass("punch-preview");
471 |         clearClass("punch-conflict");
472 |         const r = selPreviewRect(curRow,curCol);
473 |         const punchTarget = getPunchTarget(r);
474 |         if (punchTarget) {
475 |           // All cells in selection get punch-preview colour
476 |           for (let row=r.rMin;row<=r.rMax;row++)
477 |             for (let col=r.cMin;col<=r.cMax;col++)
478 |               cells[row][col].classList.add("punch-preview");
479 |         } else {
480 |           for (let row=r.rMin;row<=r.rMax;row++) {
481 |             for (let col=r.cMin;col<=r.cMax;col++) {
482 |               if (tableGrid[row][col].length > 0) {
483 |                 cells[row][col].classList.add("conflict");
484 |               } else {
485 |                 cells[row][col].classList.add("preview");
486 |               }
487 |             }
488 |           }
489 |         }
490 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
491 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
492 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
493 |         selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
494 |         selOverlay.style.display = "block";
495 |       }
496 | 
497 |       /**
498 |        * If `sel` is a valid punch rect (completely inside exactly one plain table
499 |        * with ≥1 cell margin on all sides), return that table. Otherwise null.
500 |        */
501 |       function getPunchTarget(sel) {
502 |         // Must leave at least 1-cell border → outer must be at least 3×3
503 |         const outerRMin = sel.rMin - 1, outerCMin = sel.cMin - 1;
504 |         const outerRMax = sel.rMax + 1, outerCMax = sel.cMax + 1;
505 |         if (outerRMin < 0 || outerCMin < 0 || outerRMax >= SIZE || outerCMax >= SIZE) return null;
506 |         // Every cell in the selection must belong to the same single table (type:"table")
507 |         let target = null;
508 |         for (let r=sel.rMin; r<=sel.rMax; r++) {
509 |           for (let c=sel.cMin; c<=sel.cMax; c++) {
510 |             const ids = tableGrid[r][c].filter(id => {
511 |               const p = tables.find(t => t.id === id);
512 |               return p && p.type === "table";
513 |             });
514 |             if (ids.length !== 1) return null;
515 |             const piece = tables.find(t => t.id === ids[0]);
516 |             if (!target) target = piece;
517 |             else if (target !== piece) return null;
518 |           }
519 |         }
520 |         if (!target) return null;
521 |         // The outer ring cells must all also belong to the same target
522 |         // (ensures the hole is truly interior, not on the edge of the table)
523 |         if (target.rMin > outerRMin || target.cMin > outerCMin ||
524 |             target.rMax < outerRMax || target.cMax < outerCMax) return null;
525 |         return target;
526 |       }
