529 |       // ── Cell colour helpers ──────────────────────────────────────────────────
530 |       function resetCell(r,c) {
531 |         const cell = cells[r][c];
532 |         cell.style.backgroundColor = "";
533 |         cell.style.opacity = "";
534 |         cell.classList.remove("selected","preview");
535 |         cell.classList.add((r+c)%2===0 ? "light" : "dark");
536 |         tableGrid[r][c] = [];
537 |       }
538 |       function stampTable(t) {
539 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
540 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
541 |           if (t.type === "chair") refreshChairBadge(r, c);
542 |         }
543 |       }
544 |       function eraseTable(t) {
545 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
546 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
547 |           if (tableGrid[r][c].length === 0) resetCell(r, c);
548 |           if (t.type === "chair") refreshChairBadge(r, c);
549 |         }
550 |       }
551 |       function positionEl(t) {
552 |         t.el.style.left   = (t.cMin * CELL) + "px";
553 |         t.el.style.top    = (t.rMin * CELL) + "px";
554 |         t.el.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
555 |         t.el.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
556 |       }
