558 |       // ── Table selection & edit ───────────────────────────────────────────────
559 |       function updateToolbar() {
560 |         btnTable.disabled  = !selection;
561 |         btnEdit.disabled   = !selectedTable;
562 |         btnDelete.disabled = !selectedTable;
563 |       }
564 | 
565 |       function selectTable(t) {
566 |         if (selectedTable) selectedTable.el.classList.remove("table-selected");
567 |         selectedTable = t;
568 |         if (t) t.el.classList.add("table-selected");
569 |         updateToolbar();
570 |       }
571 | 
572 |       function editTable(t) {
573 |         if (!t) return;
574 |         // Save original bounds in case user cancels
575 |         t._editBackup = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
576 |         editingTable = t;
577 |         // Lift the table off the board into the active selection
578 |         eraseTable(t);
579 |         t.el.style.display = "none";
580 |         // Load its area as the current selection
581 |         selection = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
582 |         renderSelection();
583 |         selectTable(null);
584 |       }
585 | 
586 |       function cancelEdit() {
587 |         if (!editingTable) return;
588 |         const t = editingTable;
589 |         // Restore original position
590 |         t.rMin = t._editBackup.rMin; t.cMin = t._editBackup.cMin;
591 |         t.rMax = t._editBackup.rMax; t.cMax = t._editBackup.cMax;
592 |         delete t._editBackup;
593 |         stampTable(t);
594 |         positionEl(t);
595 |         t.el.style.display = "";
596 |         editingTable = null;
597 |         // Clear selection
598 |         selection = null;
599 |         clearClass("preview"); clearClass("conflict");
600 |         renderSelection();
601 |       }
602 | 
603 |       function deleteTable(t) {
604 |         if (!t) return;
605 |         // Snapshot chair position before erasing (needed for badge refresh after splice)
606 |         const wasChair = t.type === "chair";
607 |         const chairR = t.rMin, chairC = t.cMin;
608 | 
609 |         // If this table is currently being edited, cancel the edit first
610 |         if (editingTable === t) {
611 |           editingTable = null;
612 |           delete t._editBackup;
613 |           selection = null;
614 |           clearClass("preview"); clearClass("conflict");
615 |         } else {
616 |           if (t.type === "lsofa") eraseLsofa(t);
617 |           else if (t.type === "rug") eraseRug(t);
618 |           else if (t.type === "donut") eraseDonut(t);
619 |           else eraseTable(t);
620 |         }
621 |         // Remove overlay element
622 |         if (t.el.parentNode) t.el.parentNode.removeChild(t.el);
623 |         // Remove from tables array
624 |         const idx = tables.indexOf(t);
625 |         if (idx !== -1) tables.splice(idx, 1);
626 |         // If a stacked chair was deleted, refresh the badge now that t is gone from `tables`
627 |         if (wasChair) refreshChairBadge(chairR, chairC);
628 |         // Deselect
629 |         if (selectedTable === t) selectTable(null);
630 |         renderSelection();
631 |       }
