/* ── Chaos mode ─────────────────────────────────────────────────────────── */
#btn-chaos.chaos-active {
  background: #7a1a7a;
  border-color: #d45fd4;
  animation: chaos-pulse 0.8s ease-in-out infinite alternate;
}

@keyframes chaos-pulse {
  from { box-shadow: 0 0 4px #d45fd4; }
  to   { box-shadow: 0 0 14px #d45fd4, 0 0 28px rgba(212,95,212,0.5); }
}

@keyframes teleport-flash {
  0%   { filter: brightness(3) saturate(0); opacity: 0.2; transform: scale(0.7); }
  40%  { filter: brightness(2) saturate(2); opacity: 0.9; transform: scale(1.08); }
  100% { filter: brightness(1) saturate(1); opacity: 1;   transform: scale(1); }
}

.teleporting {
  animation: teleport-flash 0.35s ease-out forwards;
  z-index: 12 !important;
}

/* ── Per-piece conflict countdown bar ───────────────────────────────────── */
.conflict-timer-bar {
  position: absolute;
  bottom: 0; left: 0;
  height: 4px;
  width: 100%;
  background: #e05555;
  transform-origin: left center;
  pointer-events: none;
  border-radius: 0 0 2px 2px;
  z-index: 13;
  transition: background 0.3s;
}
.conflict-timer-bar.urgent { background: #ff2020; box-shadow: 0 0 6px #ff2020; }

/* ── Game-over overlay ──────────────────────────────────────────────────── */
#gameover-overlay {
  position: fixed;
  inset: 0;
  background: rgba(10, 5, 20, 0.88);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 100;
  gap: 20px;
  display: none;
}
#gameover-overlay h1 {
  color: #e05555;
  font-size: 56px;
  font-weight: 900;
  letter-spacing: 2px;
  text-shadow: 0 0 24px #e05555, 0 0 48px rgba(224,85,85,0.5);
  animation: gameover-flicker 0.12s infinite alternate;
}
@keyframes gameover-flicker {
  from { opacity: 1; }
  to   { opacity: 0.85; }
}
#gameover-overlay p {
  color: #ccc;
  font-size: 18px;
  text-align: center;
  max-width: 420px;
  line-height: 1.5;
}
#gameover-overlay button {
  background: #2e4a7a;
  color: #fff;
  border: 2px solid #4a7abf;
  border-radius: 6px;
  padding: 12px 36px;
  font-size: 18px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
#gameover-overlay button:hover { background: #3a5d99; border-color: #6a9acf; }

