  // ── Chaos mode ──────────────────────────────────────────────────────────
  // Randomly teleports all furniture pieces at a fixed interval.
  // Any piece left in conflict too long causes a game over.

  const btnChaos        = document.getElementById("btn-chaos");
  const gameoverOverlay = document.getElementById("gameover-overlay");
  const gameoverMsg     = document.getElementById("gameover-msg");

  let chaosMode     = false;
  let chaosInterval = null;
  let tickInterval  = null;
  let gameOver      = false;

  const CHAOS_INTERVAL_MS  = 1200; // ms between teleport waves
  const CONFLICT_TIMEOUT   = 8000; // ms before a conflicting piece kills the game
  const TICK_MS            = 100;  // how often we check timers
  const URGENT_THRESHOLD   = 0.35; // fraction of time left that triggers "urgent" style

  // ── Conflict detection per type ─────────────────────────────────────────
  function pieceIsInConflict(t) {
    if (t.type === "lsofa")
      return hasConflictL(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant, t.id);
    if (t.type === "rug")
      return hasConflictForRug(t.cells, t.id);
    if (t.type === "donut")
      return hasConflictForDonut(t, t.id);
    if (t.type === "chair")
      return hasConflictForChair(t.rMin, t.cMin, t.id);
    // "table" and "couch"
    return hasConflict(t.rMin, t.cMin, t.rMax, t.cMax, t.id);
  }

  // ── Timer bar DOM helpers ────────────────────────────────────────────────
  function getOrCreateTimerBar(t) {
    let bar = t.el.querySelector(".conflict-timer-bar");
    if (!bar) {
      bar = document.createElement("div");
      bar.className = "conflict-timer-bar";
      t.el.appendChild(bar);
    }
    return bar;
  }

  function removeTimerBar(t) {
    const bar = t.el.querySelector(".conflict-timer-bar");
    if (bar) bar.remove();
    delete t.conflictSince;
  }

  // ── Tick: update all timers, check for game over ─────────────────────────
  function conflictTick() {
    if (gameOver) return;
    const now = Date.now();
    for (const t of tables) {
      if (pieceIsInConflict(t)) {
        if (t.conflictSince === undefined) t.conflictSince = now;
        const elapsed  = now - t.conflictSince;
        const fraction = Math.min(elapsed / CONFLICT_TIMEOUT, 1);

        if (fraction >= 1) {
          triggerGameOver(t);
          return;
        }

        const bar = getOrCreateTimerBar(t);
        bar.style.transform = `scaleX(${1 - fraction})`;
        const isUrgent = (1 - fraction) <= URGENT_THRESHOLD;
        bar.classList.toggle("urgent", isUrgent);
      } else {
        // Conflict resolved — clear timer
        if (t.conflictSince !== undefined) removeTimerBar(t);
      }
    }
  }

  // ── Game over ────────────────────────────────────────────────────────────
  function triggerGameOver(culprit) {
    gameOver = true;
    clearInterval(chaosInterval);
    clearInterval(tickInterval);
    chaosInterval = null;
    tickInterval  = null;
    chaosMode     = false;
    btnChaos.classList.remove("chaos-active");

    // Highlight the offending piece
    culprit.el.style.outline = "3px solid #e05555";
    culprit.el.style.boxShadow = "0 0 20px #e05555";

    gameoverMsg.textContent =
      `"${culprit.label || culprit.type}" sat in conflict for too long.`;
    gameoverOverlay.style.display = "flex";
  }

  // ── Teleport ─────────────────────────────────────────────────────────────
  function teleportPiece(t) {
    const r = Math.floor(Math.random() * SIZE);
    const c = Math.floor(Math.random() * SIZE);

    if (t.type === "lsofa") {
      const { cornerR: cr, cornerC: cc } = clampLsofaCorner(r, c, t.lenA, t.lenB, t.variant);
      eraseLsofa(t);
      t.cornerR = cr; t.cornerC = cc;
      stampLsofa(t);
      renderLsofaEl(t);

    } else if (t.type === "rug") {
      eraseRug(t);
      const dr = r - t.rMin, dc = c - t.cMin;
      t.cells = t.cells.map(({r: cr, c: cc}) => ({ r: cr + dr, c: cc + dc }));
      const bb = rugBBox(t.cells);
      t.rMin = bb.rMin; t.rMax = bb.rMax; t.cMin = bb.cMin; t.cMax = bb.cMax;
      stampRug(t);
      renderRugEl(t);

    } else if (t.type === "donut") {
      const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
      const newRMin = Math.min(r, SIZE - 1 - h);
      const newCMin = Math.min(c, SIZE - 1 - w);
      const dr = newRMin - t.rMin, dc = newCMin - t.cMin;
      const newHole = {
        rMin: t.hole.rMin + dr, cMin: t.hole.cMin + dc,
        rMax: t.hole.rMax + dr, cMax: t.hole.cMax + dc,
      };
      eraseDonut(t);
      t.hole = newHole;
      t.rMin = newRMin; t.cMin = newCMin; t.rMax = newRMin + h; t.cMax = newCMin + w;
      stampDonut(t);
      renderDonutEl(t);

    } else if (t.type === "chair") {
      const oldR = t.rMin, oldC = t.cMin;
      eraseTable(t);
      t.rMin = r; t.cMin = c; t.rMax = r; t.cMax = c;
      stampTable(t);
      positionEl(t);
      refreshChairBadge(oldR, oldC);
      refreshChairBadge(r, c);

    } else {
      // "table" and "couch" — keep their dimensions, clamp to board
      const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
      const newRMin = Math.min(r, SIZE - 1 - h);
      const newCMin = Math.min(c, SIZE - 1 - w);
      eraseTable(t);
      t.rMin = newRMin; t.cMin = newCMin; t.rMax = newRMin + h; t.cMax = newCMin + w;
      stampTable(t);
      positionEl(t);
    }

    // After teleporting, reset the conflict timer so the player has a fresh
    // CONFLICT_TIMEOUT from the new position, not from whenever the piece
    // first landed in trouble before.
    delete t.conflictSince;
  }

  /** Flash the teleport animation on a piece's element. */
  function flashTeleport(el) {
    el.classList.remove("teleporting");
    void el.offsetWidth; // force reflow to restart animation
    el.classList.add("teleporting");
    el.addEventListener("animationend", () => el.classList.remove("teleporting"), { once: true });
  }

  /** Teleport every piece on the board to a random position. */
  function randomTeleportAll() {
    if (gameOver) return;
    for (const t of tables) {
      if (t === movingTable) continue; // don't teleport something the user is dragging
      teleportPiece(t);
      flashTeleport(t.el);
    }
  }

  function toggleChaosMode() {
    if (gameOver) return;
    chaosMode = !chaosMode;
    if (chaosMode) {
      btnChaos.classList.add("chaos-active");
      randomTeleportAll();
      chaosInterval = setInterval(randomTeleportAll, CHAOS_INTERVAL_MS);
      tickInterval  = setInterval(conflictTick, TICK_MS);
    } else {
      btnChaos.classList.remove("chaos-active");
      clearInterval(chaosInterval);
      clearInterval(tickInterval);
      chaosInterval = null;
      tickInterval  = null;
      // Clear all timer bars when chaos is switched off
      for (const t of tables) removeTimerBar(t);
    }
  }

  btnChaos.addEventListener("click", toggleChaosMode);
</script>

