// ── Chaos mode ──────────────────────────────────────────────────────────
// Randomly teleports all furniture pieces at a fixed interval.
// Any piece left in conflict too long causes a game over.

const btnChaos        = document.getElementById("btn-chaos");
const gameoverOverlay = document.getElementById("gameover-overlay");
const gameoverMsg     = document.getElementById("gameover-msg");

let chaosMode     = false;
let chaosInterval = null;
let tickInterval  = null;
let gameOver      = false;

const CHAOS_INTERVAL_MS  = 1200; // ms between teleport waves
const CONFLICT_TIMEOUT   = 8000; // ms before a conflicting piece kills the game
const TICK_MS            = 100;  // how often we check timers
const URGENT_THRESHOLD   = 0.35; // fraction of time left that triggers "urgent" style

// ── Conflict detection per type ─────────────────────────────────────────
function pieceIsInConflict(t) {
  if (t.type === "lsofa")
    return hasConflictL(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant, t.id);
  if (t.type === "rug")
    return hasConflictForRug(t.cells, t.id);
  if (t.type === "donut")
    return hasConflictForDonut(t, t.id);
  if (t.type === "chair")
    return hasConflictForChair(t.rMin, t.cMin, t.id);
  return hasConflict(t.rMin, t.cMin, t.rMax, t.cMax, t.id);
}

// ── Timer bar DOM helpers ────────────────────────────────────────────────
function getOrCreateTimerBar(t) {
  let bar = t.el.querySelector(".conflict-timer-bar");
  if (!bar) {
    bar = document.createElement("div");
    bar.className = "conflict-timer-bar";
    t.el.appendChild(bar);
  }
  return bar;
}

function removeTimerBar(t) {
  const bar = t.el.querySelector(".conflict-timer-bar");
  if (bar) bar.remove();
  delete t.conflictSince;
}

