426 |     <script>
427 |       const CELL = 12, SIZE = 64;
428 |       const board     = document.getElementById("board");
429 |       const overlay   = document.getElementById("overlay");
430 |       const selOverlay = document.getElementById("selection-overlay");
431 |       const btnTable  = document.getElementById("btn-table");
432 |       const btnCouch  = document.getElementById("btn-couch");
433 |       const btnLsofa  = document.getElementById("btn-lsofa");
434 |       const btnChair  = document.getElementById("btn-chair");
435 |       const btnRug    = document.getElementById("btn-rug");
436 |       const btnEdit   = document.getElementById("btn-edit");
437 |       const btnDelete = document.getElementById("btn-delete");
438 |       const boardWrap = document.getElementById("board-wrap");
439 |       const couchGhostEl = document.getElementById("couch-ghost");
440 |       const chairGhostEl = document.getElementById("chair-ghost");
441 |       const lsofaGhostEl = document.getElementById("lsofa-ghost");
442 |       const lsofaGhostCanvas = document.getElementById("lsofa-ghost-canvas");
443 |       const rugCounterEl = document.getElementById("rug-counter");
444 | 
445 |       const TABLE_COLORS = [
446 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
447 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
448 |       ];
449 | 
450 |       // ── State ────────────────────────────────────────────────────────────────
451 |       let tableCount = 0;
452 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
453 |       const tableGrid = [];   // tableGrid[row][col] = array of piece ids occupying that cell
454 |       let selectedTable = null;   // table currently clicked/focused
455 |       let editingTable  = null;   // table lifted into edit mode
456 | 
457 |       let couchCount = 0;
458 |       let couchMode  = false;     // true while couch-placement is active
459 |       let ghostOrientation = "h"; // "h" or "v" — orientation of the next couch to be placed
460 | 
461 |       let chairCount = 0;
462 |       let chairMode  = false;
463 | 
464 |       let lsofaCount = 0;
465 |       let lsofaMode  = false;
466 |       // Variants: "se" "sw" "ne" "nw" — which direction the two arms extend from the corner
467 |       let lsofaVariant = "se";
468 |       // Ghost arm lengths (editable via handles during placement ghost drag)
469 |       let lsofaGhostLenA = 3; // horizontal arm (min 2)
470 |       let lsofaGhostLenB = 3; // vertical arm   (min 2)
471 | 
472 |       let rugCount = 0;
473 |       let rugMode  = false;
474 |       const RUG_MAX_CELLS = 16;
475 |       let rugPaintCells = new Set();
476 | 
477 |       let donutCount = 0;
478 |       const DONUT_MIN_ROWS = 3, DONUT_MIN_COLS = 3;
479 |       const DONUT_MAX_ROWS = 16, DONUT_MAX_COLS = 24;
480 | 
481 |       // ── Build cell grid ──────────────────────────────────────────────────────
482 |       const cells = [];
483 |       for (let row = 0; row < SIZE; row++) {
484 |         cells[row] = []; tableGrid[row] = [];
485 |         for (let col = 0; col < SIZE; col++) {
486 |           const cell = document.createElement("div");
487 |           cell.classList.add("cell");
488 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
489 |           cell.dataset.row = row; cell.dataset.col = col;
490 |           cells[row][col] = cell; tableGrid[row][col] = [];
491 |           board.appendChild(cell);
492 |         }
493 |       }
494 | 
495 |       // ── Selection helpers ────────────────────────────────────────────────────
496 |       let selection = null;
497 |       let isSelecting = false, selStartRow = null, selStartCol = null;
498 | 
499 |       function clearClass(cls) {
500 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
501 |       }
502 |       function paintRect(r1,c1,r2,c2,cls) {
503 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
504 |       }
505 |       function renderSelection() {
506 |         clearClass("selected");
507 |         if (selection) {
508 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
509 |           selOverlay.style.left    = (selection.cMin * CELL) + "px";
510 |           selOverlay.style.top     = (selection.rMin * CELL) + "px";
511 |           selOverlay.style.width   = ((selection.cMax - selection.cMin + 1) * CELL) + "px";
512 |           selOverlay.style.height  = ((selection.rMax - selection.rMin + 1) * CELL) + "px";
513 |           selOverlay.style.display = "block";
514 |         } else {
515 |           selOverlay.style.display = "none";
516 |         }
517 |         btnTable.disabled = !selection;
518 |         btnEdit.disabled  = !selectedTable;
519 |       }
520 |       function selPreviewRect(curRow,curCol) {
521 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
522 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
523 |         let raw;
524 |         if (!selection) raw = {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
525 |         else raw = {
526 |           rMin:Math.min(selection.rMin,dr1), cMin:Math.min(selection.cMin,dc1),
527 |           rMax:Math.max(selection.rMax,dr2), cMax:Math.max(selection.cMax,dc2),
528 |         };
529 |         const { rMin, cMin, rMax, cMax } = raw;
530 |         return clampTableSelection(rMin, cMin, rMax, cMax);
531 |       }
532 |       function applySelPreview(curRow,curCol) {
533 |         clearClass("preview");
534 |         clearClass("conflict");
535 |         clearClass("punch-preview");
536 |         clearClass("punch-conflict");
537 |         const r = selPreviewRect(curRow,curCol);
538 |         const punchTarget = getPunchTarget(r);
539 |         if (punchTarget) {
540 |           // All cells in selection get punch-preview colour
541 |           for (let row=r.rMin;row<=r.rMax;row++)
542 |             for (let col=r.cMin;col<=r.cMax;col++)
543 |               cells[row][col].classList.add("punch-preview");
544 |         } else {
545 |           for (let row=r.rMin;row<=r.rMax;row++) {
546 |             for (let col=r.cMin;col<=r.cMax;col++) {
547 |               if (tableGrid[row][col].length > 0) {
548 |                 cells[row][col].classList.add("conflict");
549 |               } else {
550 |                 cells[row][col].classList.add("preview");
551 |               }
552 |             }
553 |           }
554 |         }
555 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
556 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
557 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
558 |         selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
559 |         selOverlay.style.display = "block";
560 |       }
561 | 
562 |       /**
563 |        * If `sel` is a valid punch rect (completely inside exactly one plain table
564 |        * with ≥1 cell margin on all sides), return that table. Otherwise null.
565 |        */
566 |       function getPunchTarget(sel) {
567 |         // Must leave at least 1-cell border → outer must be at least 3×3
568 |         const outerRMin = sel.rMin - 1, outerCMin = sel.cMin - 1;
569 |         const outerRMax = sel.rMax + 1, outerCMax = sel.cMax + 1;
570 |         if (outerRMin < 0 || outerCMin < 0 || outerRMax >= SIZE || outerCMax >= SIZE) return null;
571 |         // Every cell in the selection must belong to the same single table (type:"table")
572 |         let target = null;
573 |         for (let r=sel.rMin; r<=sel.rMax; r++) {
574 |           for (let c=sel.cMin; c<=sel.cMax; c++) {
575 |             const ids = tableGrid[r][c].filter(id => {
576 |               const p = tables.find(t => t.id === id);
577 |               return p && p.type === "table";
578 |             });
579 |             if (ids.length !== 1) return null;
580 |             const piece = tables.find(t => t.id === ids[0]);
581 |             if (!target) target = piece;
582 |             else if (target !== piece) return null;
583 |           }
584 |         }
585 |         if (!target) return null;
586 |         // The outer ring cells must all also belong to the same target
587 |         // (ensures the hole is truly interior, not on the edge of the table)
588 |         if (target.rMin > outerRMin || target.cMin > outerCMin ||
589 |             target.rMax < outerRMax || target.cMax < outerCMax) return null;
590 |         return target;
591 |       }
