728 |       /** Enforce table size limits on a raw selection rect. Returns clamped rect. */
729 |       function clampTableSelection(rMin, cMin, rMax, cMax) {
730 |         const rows = rMax - rMin + 1, cols = cMax - cMin + 1;
731 |         // Enforce minimum
732 |         const r2 = Math.min(rMin + Math.max(rows, TABLE_MIN_ROWS) - 1, SIZE - 1);
733 |         const c2 = Math.min(cMin + Math.max(cols, TABLE_MIN_COLS) - 1, SIZE - 1);
734 |         // Enforce maximum
735 |         const r3 = Math.min(r2, rMin + TABLE_MAX_ROWS - 1);
736 |         const c3 = Math.min(c2, cMin + TABLE_MAX_COLS - 1);
737 |         return { rMin, cMin, rMax: r3, cMax: c3 };
