740 |       /**
741 |        * Fracture any type:"table" pieces whose footprint overlaps the given rect.
742 |        * The overlapping table is deleted and replaced by up to 4 non-overlapping
743 |        * rectangular shards (top / bottom / left strip / right strip) using a
744 |        * guillotine cut around the intersection.
745 |        * Call this AFTER the new piece has been stamped so tableGrid is current.
746 |        * Pass the new piece's id as `ignoreId` so we don't fracture the piece itself.
747 |        */
748 |       function fractureTablesUnder(nR1, nC1, nR2, nC2, ignoreId) {
749 |         // Collect every table-type piece whose cells overlap the new rect
750 |         const victims = new Set();
751 |         for (let r = nR1; r <= nR2; r++) {
752 |           for (let c = nC1; c <= nC2; c++) {
753 |             for (const tid of tableGrid[r][c]) {
754 |               if (tid === ignoreId) continue;
755 |               const p = tables.find(t => t.id === tid);
756 |               if (p && p.type === "table") victims.add(p);
757 |             }
758 |           }
759 |         }
760 |         for (const victim of victims) {
761 |           // Intersection of victim with the new rect
762 |           const oR1 = Math.max(victim.rMin, nR1), oC1 = Math.max(victim.cMin, nC1);
763 |           const oR2 = Math.min(victim.rMax, nR2), oC2 = Math.min(victim.cMax, nC2);
764 |           if (oR1 > oR2 || oC1 > oC2) continue; // no actual overlap (shouldn't happen)
765 | 
766 |           // Remember bounds before deletion
767 |           const vR1 = victim.rMin, vC1 = victim.cMin;
768 |           const vR2 = victim.rMax, vC2 = victim.cMax;
769 |           const vColor = victim.color;
770 | 
771 |           deleteTable(victim);
772 | 
773 |           // Up to 4 shards — each only created if non-empty
774 |           const shards = [
775 |             { rMin: vR1,    cMin: vC1,    rMax: oR1-1, cMax: vC2    }, // top
776 |             { rMin: oR2+1,  cMin: vC1,    rMax: vR2,   cMax: vC2    }, // bottom
777 |             { rMin: oR1,    cMin: vC1,    rMax: oR2,   cMax: oC1-1  }, // left
778 |             { rMin: oR1,    cMin: oC2+1,  rMax: oR2,   cMax: vC2    }, // right
779 |           ];
780 |           for (const s of shards) {
781 |             if (s.rMin > s.rMax || s.cMin > s.cMax) continue; // empty shard
782 |             spawnTable(s.rMin, s.cMin, s.rMax, s.cMax, vColor);
783 |           }
784 |         }
785 |       }
