1008 |       /** Rotate a plain rectangular table 90° CW around its top-left corner. */
1009 |       function rotateTable(t) {
1010 |         const h = t.rMax - t.rMin; // span in rows (0-based delta)
1011 |         const w = t.cMax - t.cMin; // span in cols (0-based delta)
1012 |         // After CW rotation, rows←cols and cols←rows
1013 |         const newRowSpan = w, newColSpan = h; // 0-based deltas
1014 |         const newRows = newRowSpan + 1, newCols = newColSpan + 1;
1015 |         // Enforce min/max bounds — skip rotation if it would violate them
1016 |         if (newRows < TABLE_MIN_ROWS || newCols < TABLE_MIN_COLS) return;
1017 |         if (newRows > TABLE_MAX_ROWS || newCols > TABLE_MAX_COLS) return;
1018 |         const newRMax = Math.min(t.rMin + newRowSpan, SIZE - 1);
1019 |         const newCMax = Math.min(t.cMin + newColSpan, SIZE - 1);
1020 |         eraseTable(t);
1021 |         t.rMax = newRMax;
1022 |         t.cMax = newCMax;
1023 |         stampTable(t);
1024 |         positionEl(t);
