1033 |           return { r: t.rMin + dc, c: t.cMin + (H - 1 - dr) };
1034 |         });
1035 |         // Clamp so we stay on the board
1036 |         const bb = rugBBox(rotated);
1037 |         const dr = Math.max(0, -bb.rMin) + Math.min(0, SIZE - 1 - bb.rMax);
1038 |         const dc = Math.max(0, -bb.cMin) + Math.min(0, SIZE - 1 - bb.cMax);
1039 |         const clamped = rotated.map(({r, c}) => ({ r: r + dr, c: c + dc }));
1040 |         eraseRug(t);
1041 |         t.cells = clamped;
1042 |         stampRug(t);
