1206 |       // ── L-shape sofa ─────────────────────────────────────────────────────────
1207 |       // An L-sofa is defined by:
1208 |       //   corner:  (cornerR, cornerC) — the inner corner cell
1209 |       //   lenA:    horizontal arm length (≥ 2)
1210 |       //   lenB:    vertical arm length   (≥ 2)
1211 |       //   variant: "se" | "sw" | "ne" | "nw"
1212 |       //
1213 |       //  "se": H arm → right, V arm → down   (corner = top-left  of bbox)
1214 |       //  "sw": H arm → left,  V arm → down   (corner = top-right)
1215 |       //  "ne": H arm → right, V arm → up     (corner = bottom-left)
1216 |       //  "nw": H arm → left,  V arm → up     (corner = bottom-right)
1217 | 
1218 |       const LSOFA_COLORS = [
1219 |         "#c0703c","#3c8fc0","#7ac03c","#c03c8a",
1220 |         "#3cc09a","#c0b03c","#803cc0","#c05a3c",
1221 |       ];
1222 |       const LSOFA_VARIANT_CYCLE = ["se","sw","nw","ne"];
