1224 |       function lsofaBBox(cornerR, cornerC, lenA, lenB, variant) {
1225 |         switch (variant) {
1226 |           case "se": return { rMin: cornerR,            cMin: cornerC,            rMax: cornerR + lenB - 1, cMax: cornerC + lenA - 1 };
1227 |           case "sw": return { rMin: cornerR,            cMin: cornerC - lenA + 1, rMax: cornerR + lenB - 1, cMax: cornerC };
1228 |           case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,            rMax: cornerR,            cMax: cornerC + lenA - 1 };
1229 |           case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,            cMax: cornerC };
1230 |         }
1231 |       }
1232 | 
1233 |       function lsofaCells(cornerR, cornerC, lenA, lenB, variant) {
1234 |         const out = []; const seen = new Set();
1235 |         const add = (r,c) => { const k=r+","+c; if(!seen.has(k)){seen.add(k);out.push({r,c});} };
1236 |         for (let i = 0; i < lenA; i++) add(cornerR, (variant==="sw"||variant==="nw") ? cornerC-i : cornerC+i);
1237 |         for (let i = 0; i < lenB; i++) add((variant==="ne"||variant==="nw") ? cornerR-i : cornerR+i, cornerC);
1238 |         return out;
1239 |       }
1240 | 
1241 |       function clampLsofaCorner(cornerR, cornerC, lenA, lenB, variant) {
1242 |         const bb = lsofaBBox(cornerR, cornerC, lenA, lenB, variant);
1243 |         let dr=0, dc=0;
1244 |         if (bb.rMin < 0)     dr = -bb.rMin;
1245 |         if (bb.rMax >= SIZE) dr = SIZE - 1 - bb.rMax;
1246 |         if (bb.cMin < 0)     dc = -bb.cMin;
1247 |         if (bb.cMax >= SIZE) dc = SIZE - 1 - bb.cMax;
1248 |         return { cornerR: cornerR+dr, cornerC: cornerC+dc };
1249 |       }
1250 | 
1251 |       function hasConflictL(cornerR, cornerC, lenA, lenB, variant, ignoreId=null) {
1252 |         for (const {r,c} of lsofaCells(cornerR, cornerC, lenA, lenB, variant))
1253 |           for (const tid of tableGrid[r][c]) if (tid !== ignoreId) return true;
1254 |         return false;
1255 |       }
