1257 |       function stampLsofa(t) {
1258 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
1259 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
1260 |         }
1261 |       }
