1263 |       function eraseLsofa(t) {
1264 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
1265 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
1266 |           if (tableGrid[r][c].length === 0) resetCell(r,c);
