1270 |       /** Draw the L polygon onto a canvas context. */
1271 |       function drawLshape(ctx, W, H, lenA, lenB, variant, fillColor, strokeColor, conflict) {
1272 |         ctx.clearRect(0, 0, W, H);
1273 |         ctx.beginPath();
1274 |         switch (variant) {
1275 |           case "se":
1276 |             ctx.moveTo(0,    0);    ctx.lineTo(W,    0);
1277 |             ctx.lineTo(W,    CELL); ctx.lineTo(CELL, CELL);
1278 |             ctx.lineTo(CELL, H);    ctx.lineTo(0,    H);
1279 |             break;
1280 |           case "sw":
1281 |             ctx.moveTo(W,      0);    ctx.lineTo(0,      0);
1282 |             ctx.lineTo(0,      CELL); ctx.lineTo(W-CELL, CELL);
1283 |             ctx.lineTo(W-CELL, H);    ctx.lineTo(W,      H);
1284 |             break;
1285 |           case "ne":
1286 |             ctx.moveTo(0,    H);      ctx.lineTo(W,    H);
1287 |             ctx.lineTo(W,    H-CELL); ctx.lineTo(CELL, H-CELL);
1288 |             ctx.lineTo(CELL, 0);      ctx.lineTo(0,    0);
1289 |             break;
1290 |           case "nw":
1291 |             ctx.moveTo(W,      H);      ctx.lineTo(0,      H);
1292 |             ctx.lineTo(0,      H-CELL); ctx.lineTo(W-CELL, H-CELL);
1293 |             ctx.lineTo(W-CELL, 0);      ctx.lineTo(W,      0);
1294 |             break;
1295 |         }
1296 |         ctx.closePath();
1297 |         ctx.fillStyle   = conflict ? "rgba(255,60,60,0.35)"  : fillColor;
1298 |         ctx.strokeStyle = conflict ? "rgba(255,80,80,0.9)"   : strokeColor;
1299 |         ctx.lineWidth = 2; ctx.fill(); ctx.stroke();
1300 |       }
