input.new_text:
/* ── Per-piece conflict countdown bar ───────────────────────────────────── */
.conflict-timer-bar {
  position: absolute;
  bottom: 0; left: 0;
  height: 4px;
  width: 100%;
  background: #e05555;
  transform-origin: left center;
  pointer-events: none;
  border-radius: 0 0 2px 2px;
  z-index: 13;
  transition: background 0.3s;
}
.conflict-timer-bar.urgent { background: #ff2020; box-shadow: 0 0 6px #ff2020; }

/* ── Broken furniture ───────────────────────────────────────────────────── */
.broken-bar {
  position: absolute;
  top: 0; left: 0;
  height: 4px;
  width: 100%;
  background: #e8a020;
  transform-origin: left center;
  pointer-events: none;
  border-radius: 2px 2px 0 0;
  z-index: 13;
  transition: background 0.3s;
}
.broken-bar.urgent { background: #ff6000; box-shadow: 0 0 6px #ff6000; }

.table-rect.broken,
.chair-rect.broken,
.couch-rect.broken,
.lsofa-rect.broken,
.rug-rect.broken,
.donut-rect.broken {
  cursor: pointer !important;
  animation: broken-shake 0.18s ease-in-out infinite alternate;
  filter: brightness(0.6) sepia(1) hue-rotate(-20deg) saturate(3);
  outline: 2px dashed #ff9900 !important;
}

@keyframes broken-shake {
  from { transform: translate(-1px, 0) rotate(-0.8deg); }
  to   { transform: translate( 1px, 0) rotate( 0.8deg); }
}

.broken-icon {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 18px;
  pointer-events: none;
  z-index: 14;
  filter: drop-shadow(0 0 3px #000);
  line-height: 1;
}

