function removeTimerBar(t) {
  const bar = t.el.querySelector(".conflict-timer-bar");
  if (bar) bar.remove();
  delete t.conflictSince;
}

// ── Broken state helpers ─────────────────────────────────────────────────
function breakPiece(t) {
  if (t.broken) return; // already broken
  t.broken = true;
  t.brokenSince = Date.now();
  t.el.classList.add("broken");

  // Add the wrench icon if there isn't one yet
  if (!t.el.querySelector(".broken-icon")) {
    const icon = document.createElement("span");
    icon.className = "broken-icon";
    icon.textContent = "🔧";
    t.el.appendChild(icon);
  }

  // Add the countdown bar at the top
  if (!t.el.querySelector(".broken-bar")) {
    const bar = document.createElement("div");
    bar.className = "broken-bar";
    t.el.appendChild(bar);
  }
}

function fixPiece(t) {
  if (!t.broken) return;
  t.broken = false;
  delete t.brokenSince;
  t.el.classList.remove("broken");
  const icon = t.el.querySelector(".broken-icon");
  if (icon) icon.remove();
  const bar = t.el.querySelector(".broken-bar");
  if (bar) bar.remove();
}

// Randomly break one piece that isn't already broken
function randomBreakEvent() {
  if (gameOver) return;
  const eligible = tables.filter(t => !t.broken);
  if (!eligible.length) return;
  // Pick exactly one at random
  const pick = eligible[Math.floor(Math.random() * eligible.length)];
  breakPiece(pick);
}

