// ── Tick: update all timers, check for game over ─────────────────────────
function conflictTick() {
  if (gameOver) return;
  const now = Date.now();
  for (const t of tables) {
    // ── Conflict timer (bottom bar) ───────────────────────────────────────
    if (pieceIsInConflict(t)) {
      if (t.conflictSince === undefined) t.conflictSince = now;
      const elapsed  = now - t.conflictSince;
      const fraction = Math.min(elapsed / CONFLICT_TIMEOUT, 1);
      if (fraction >= 1) { triggerGameOver(t, "conflict"); return; }
      const bar = getOrCreateTimerBar(t);
      bar.style.transform = `scaleX(${1 - fraction})`;
      bar.classList.toggle("urgent", (1 - fraction) <= URGENT_THRESHOLD);
    } else {
      if (t.conflictSince !== undefined) removeTimerBar(t);
    }

    // ── Broken timer (top bar) ────────────────────────────────────────────
    if (t.broken) {
      const elapsed  = now - t.brokenSince;
      const fraction = Math.min(elapsed / BREAK_TIMEOUT, 1);
      if (fraction >= 1) { triggerGameOver(t, "broken"); return; }
      const bar = t.el.querySelector(".broken-bar");
      if (bar) {
        bar.style.transform = `scaleX(${1 - fraction})`;
        bar.classList.toggle("urgent", (1 - fraction) <= URGENT_THRESHOLD);
      }
    }
  }
}

// ── Game over ────────────────────────────────────────────────────────────
function triggerGameOver(culprit, reason) {
  gameOver = true;
  clearInterval(chaosInterval);
  clearInterval(tickInterval);
  clearInterval(breakInterval);
  chaosInterval = null; tickInterval = null; breakInterval = null;
  chaosMode = false;
  btnChaos.classList.remove("chaos-active");
  culprit.el.style.outline   = "3px solid #e05555";
  culprit.el.style.boxShadow = "0 0 20px #e05555";
  const name = culprit.label || culprit.type;
  gameoverMsg.textContent = reason === "broken"
    ? `"${name}" broke and wasn't fixed in time.`
    : `"${name}" sat in conflict for too long.`;
  gameoverOverlay.style.display = "flex";
}

