1267 |       function lsofaBBox(cornerR, cornerC, lenA, lenB, variant) {
1268 |         switch (variant) {
1269 |           case "se": return { rMin: cornerR,            cMin: cornerC,            rMax: cornerR + lenB - 1, cMax: cornerC + lenA - 1 };
1270 |           case "sw": return { rMin: cornerR,            cMin: cornerC - lenA + 1, rMax: cornerR + lenB - 1, cMax: cornerC };
1271 |           case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,            rMax: cornerR,            cMax: cornerC + lenA - 1 };
1272 |           case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,            cMax: cornerC };
1273 |         }
1274 |       }
1275 | 
1276 |       function lsofaCells(cornerR, cornerC, lenA, lenB, variant) {
1277 |         const out = []; const seen = new Set();
1278 |         const add = (r,c) => { const k=r+","+c; if(!seen.has(k)){seen.add(k);out.push({r,c});} };
1279 |         for (let i = 0; i < lenA; i++) add(cornerR, (variant==="sw"||variant==="nw") ? cornerC-i : cornerC+i);
1280 |         for (let i = 0; i < lenB; i++) add((variant==="ne"||variant==="nw") ? cornerR-i : cornerR+i, cornerC);
1281 |         return out;
1282 |       }
