1284 |       function clampLsofaCorner(cornerR, cornerC, lenA, lenB, variant) {
1285 |         const bb = lsofaBBox(cornerR, cornerC, lenA, lenB, variant);
1286 |         let dr=0, dc=0;
1287 |         if (bb.rMin < 0)     dr = -bb.rMin;
1288 |         if (bb.rMax >= SIZE) dr = SIZE - 1 - bb.rMax;
1289 |         if (bb.cMin < 0)     dc = -bb.cMin;
1290 |         if (bb.cMax >= SIZE) dc = SIZE - 1 - bb.cMax;
