1316 |         ctx.beginPath();
1317 |         switch (variant) {
1318 |           case "se":
1319 |             ctx.moveTo(0,    0);    ctx.lineTo(W,    0);
1320 |             ctx.lineTo(W,    CELL); ctx.lineTo(CELL, CELL);
1321 |             ctx.lineTo(CELL, H);    ctx.lineTo(0,    H);
1322 |             break;
1323 |           case "sw":
1324 |             ctx.moveTo(W,      0);    ctx.lineTo(0,      0);
1325 |             ctx.lineTo(0,      CELL); ctx.lineTo(W-CELL, CELL);
1326 |             ctx.lineTo(W-CELL, H);    ctx.lineTo(W,      H);
1327 |             break;
1328 |           case "ne":
1329 |             ctx.moveTo(0,    H);      ctx.lineTo(W,    H);
1330 |             ctx.lineTo(W,    H-CELL); ctx.lineTo(CELL, H-CELL);
1331 |             ctx.lineTo(CELL, 0);      ctx.lineTo(0,    0);
1332 |             break;
1333 |           case "nw":
1334 |             ctx.moveTo(W,      H);      ctx.lineTo(0,      H);
1335 |             ctx.lineTo(0,      H-CELL); ctx.lineTo(W-CELL, H-CELL);
1336 |             ctx.lineTo(W-CELL, 0);      ctx.lineTo(W,      0);
1337 |             break;
