 741 |       // ── Conflict detection ───────────────────────────────────────────────────
 742 |       // Returns true if the given rect overlaps any piece (optionally ignoring one id).
 743 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
 744 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
 745 |           for (const tid of tableGrid[r][c]) {
 746 |             if (tid !== ignoreId) return true;
 747 |           }
 748 |         }
 749 |         return false;
 750 |       }
 751 | 
 752 |       // Chair-specific conflict: only blocks on non-chair pieces (chairs can stack).
 753 |       function hasConflictForChair(row, col, ignoreId=null) {
 754 |         for (const tid of tableGrid[row][col]) {
 755 |           if (tid === ignoreId) continue;
 756 |           const piece = tables.find(t => t.id === tid);
 757 |           if (piece && piece.type !== "chair") return true;
 758 |         }
 759 |         return false;
 760 |       }
 761 | 
 762 |       // Couch-specific conflict: blocks on any other piece — couches cannot stack.
 763 |       function hasConflictForCouch(rMin, cMin, rMax, cMax, ignoreId=null) {
 764 |         return hasConflict(rMin, cMin, rMax, cMax, ignoreId);
 765 |       }
 766 | 
 767 |       // ── Place Table ──────────────────────────────────────────────────────────
 768 |       const TABLE_MIN_ROWS = 2, TABLE_MIN_COLS = 3;
 769 |       const TABLE_MAX_ROWS = 16, TABLE_MAX_COLS = 24;
 770 | 
 771 |       /** Enforce table size limits on a raw selection rect. Returns clamped rect. */
 772 |       function clampTableSelection(rMin, cMin, rMax, cMax) {
 773 |         const rows = rMax - rMin + 1, cols = cMax - cMin + 1;
 774 |         // Enforce minimum
 775 |         const r2 = Math.min(rMin + Math.max(rows, TABLE_MIN_ROWS) - 1, SIZE - 1);
 776 |         const c2 = Math.min(cMin + Math.max(cols, TABLE_MIN_COLS) - 1, SIZE - 1);
 777 |         // Enforce maximum
 778 |         const r3 = Math.min(r2, rMin + TABLE_MAX_ROWS - 1);
 779 |         const c3 = Math.min(c2, cMin + TABLE_MAX_COLS - 1);
