1051 |       /** Rotate a plain rectangular table 90° CW around its top-left corner. */
1052 |       function rotateTable(t) {
1053 |         const h = t.rMax - t.rMin; // span in rows (0-based delta)
1054 |         const w = t.cMax - t.cMin; // span in cols (0-based delta)
1055 |         // After CW rotation, rows←cols and cols←rows
1056 |         const newRowSpan = w, newColSpan = h; // 0-based deltas
1057 |         const newRows = newRowSpan + 1, newCols = newColSpan + 1;
1058 |         // Enforce min/max bounds — skip rotation if it would violate them
1059 |         if (newRows < TABLE_MIN_ROWS || newCols < TABLE_MIN_COLS) return;
1060 |         if (newRows > TABLE_MAX_ROWS || newCols > TABLE_MAX_COLS) return;
1061 |         const newRMax = Math.min(t.rMin + newRowSpan, SIZE - 1);
1062 |         const newCMax = Math.min(t.cMin + newColSpan, SIZE - 1);
1063 |         eraseTable(t);
1064 |         t.rMax = newRMax;
1065 |         t.cMax = newCMax;
1066 |         stampTable(t);
1067 |         positionEl(t);
1068 |       }
