1070 |       /** Rotate a rug's cells 90° CW, keeping bounding-box top-left fixed. */
1071 |       function rotateRug(t) {
1072 |         const H = t.rMax - t.rMin + 1; // current bbox height
1073 |         // 90° CW around top-left: (dr, dc) → (dc, H-1-dr)
1074 |         const rotated = t.cells.map(({r, c}) => {
1075 |           const dr = r - t.rMin, dc = c - t.cMin;
1076 |           return { r: t.rMin + dc, c: t.cMin + (H - 1 - dr) };
1077 |         });
1078 |         // Clamp so we stay on the board
1079 |         const bb = rugBBox(rotated);
1080 |         const dr = Math.max(0, -bb.rMin) + Math.min(0, SIZE - 1 - bb.rMax);
1081 |         const dc = Math.max(0, -bb.cMin) + Math.min(0, SIZE - 1 - bb.cMax);
1082 |         const clamped = rotated.map(({r, c}) => ({ r: r + dr, c: c + dc }));
1083 |         eraseRug(t);
1084 |         t.cells = clamped;
1085 |         stampRug(t);
1086 |         renderRugEl(t);
1087 |       }
