function randomBreakEvent() {
  if (gameOver) return;
  const eligible = tables.filter(t => !t.broken);
  if (!eligible.length) return;
  // Pick exactly one at random
  const pick = eligible[Math.floor(Math.random() * eligible.length)];
  breakPiece(pick);
}

// ── Fade helpers ─────────────────────────────────────────────────────────
function fadePiece(t) {
  if (t.fading) return;
  t.fading    = true;
  t.fadePhase = Math.random() * Math.PI * 2; // random start point in the cycle
  t.fadeSpeed = FADE_SPEED_MIN +
                Math.random() * (FADE_SPEED_MAX - FADE_SPEED_MIN); // rad/sec
}

function unfadePiece(t) {
  if (!t.fading) return;
  t.fading = false;
  delete t.fadePhase;
  delete t.fadeSpeed;
  // Only restore opacity if the piece isn't in another state that overrides it
  if (t !== movingTable) t.el.style.opacity = "";
}

function randomFadeEvent() {
  if (gameOver) return;
  // Stop one currently-fading piece (if any)
  const fading = tables.filter(t => t.fading);
  if (fading.length > 0 && Math.random() < 0.5) {
    unfadePiece(fading[Math.floor(Math.random() * fading.length)]);
  }
  // Start fading one non-fading piece
  const still = tables.filter(t => !t.fading);
  if (still.length > 0) {
    fadePiece(still[Math.floor(Math.random() * still.length)]);
  }
}

