const FADE_INTERVAL_MS   = 2500; // ms between random fade start/stop events
const FADE_SPEED_MIN     = 1.5;  // radians/sec — slowest pulse
const FADE_SPEED_MAX     = 4.0;  // radians/sec — fastest pulse

// ── Rainbow easter egg ───────────────────────────────────────────────────
// 1/100 chance on placement. Piece cycles through full hue spectrum.
let rainbowRafId = null;

function applyRainbowColor(t, hue) {
  const fill   = `hsla(${hue}, 85%, 58%, 0.55)`;
  const stroke = `hsl(${hue}, 85%, 45%)`;
  if (t.type === "table" || t.type === "couch" || t.type === "chair") {
    t.el.style.backgroundColor = fill;
    t.el.style.borderColor     = stroke;
  } else if (t.type === "lsofa") {
    const bb = lsofaBBox(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant);
    const W = (bb.cMax - bb.cMin + 1) * CELL, H = (bb.rMax - bb.rMin + 1) * CELL;
    drawLshape(t.canvas.getContext("2d"), W, H, t.lenA, t.lenB, t.variant, fill, stroke, false);
  } else if (t.type === "rug") {
    const bb = rugBBox(t.cells);
    const W = (bb.cMax - bb.cMin + 1) * CELL, H = (bb.rMax - bb.rMin + 1) * CELL;
    drawRug(t.canvas.getContext("2d"), W, H, t.cells, bb.rMin, bb.cMin, fill, stroke);
  } else if (t.type === "donut") {
    const W = (t.cMax - t.cMin + 1) * CELL, H = (t.rMax - t.rMin + 1) * CELL;
    const holeX = (t.hole.cMin - t.cMin) * CELL, holeY = (t.hole.rMin - t.rMin) * CELL;
    const holeW = (t.hole.cMax - t.hole.cMin + 1) * CELL;
    const holeH = (t.hole.rMax - t.hole.rMin + 1) * CELL;
    drawDonut(t.canvas.getContext("2d"), W, H, holeX, holeY, holeW, holeH, fill, stroke, false);
  }
}

function rainbowPiece(t) {
  t.rainbow      = true;
  t.rainbowPhase = Math.random() * 360; // random start hue
  if (!rainbowRafId) startRainbowLoop();
}

function unrainbowPiece(t) {
  if (!t.rainbow) return;
  t.rainbow = false;
  delete t.rainbowPhase;
  // Restore original flat color
  const fill   = t.color + (t.type === "table" ? "44" : t.type === "couch" ? "55" :
                  t.type === "chair" ? "88" : "99");
  const stroke = t.color;
  if (t.type === "table" || t.type === "couch" || t.type === "chair") {
    t.el.style.backgroundColor = fill;
    t.el.style.borderColor     = stroke;
  } else if (t.type === "lsofa") {
    renderLsofaEl(t);
  } else if (t.type === "rug") {
    renderRugEl(t);
  } else if (t.type === "donut") {
    renderDonutEl(t);
  }
}

function startRainbowLoop() {
  let last = performance.now();
  function frame(now) {
    const dt  = (now - last) / 1000;
    last = now;
    let any = false;
    for (const t of tables) {
      if (!t.rainbow) continue;
      any = true;
      t.rainbowPhase = (t.rainbowPhase + dt * 60) % 360; // ~60°/sec
      applyRainbowColor(t, t.rainbowPhase);
    }
    rainbowRafId = any ? requestAnimationFrame(frame) : null;
  }
  rainbowRafId = requestAnimationFrame(frame);
}

function maybeRainbow(t) {
  if (Math.random() < 0.01) rainbowPiece(t);
}

