// ── Rug squiggle ─────────────────────────────────────────────────────────
// Each tick: remove one removable boundary cell, grow one adjacent empty cell.
// Runs SQUIGGLE_STEPS times per tick so the rug visibly writhes.

function squiggleRug(t) {
  if (t === movingTable) return;
  const DIRS = [[-1,0],[1,0],[0,-1],[0,1]];

  for (let step = 0; step < SQUIGGLE_STEPS; step++) {
    const cellSet = new Set(t.cells.map(({r,c}) => `${r},${c}`));

    // ── Candidates to remove: boundary cells that keep the shape connected ──
    const removable = [];
    for (const key of cellSet) {
      // A cell is a "boundary" cell if it has at least one empty 4-neighbour
      const [r,c] = key.split(",").map(Number);
      const isBoundary = DIRS.some(([dr,dc]) => !cellSet.has(`${r+dr},${c+dc}`));
      if (isBoundary && rugCanRemove(cellSet, key)) removable.push(key);
    }
    if (!removable.length) continue;

    // ── Candidates to grow: empty on-board cells adjacent to the shape ──
    const growable = [];
    const checked  = new Set();
    for (const key of cellSet) {
      const [r,c] = key.split(",").map(Number);
      for (const [dr,dc] of DIRS) {
        const nr = r+dr, nc = c+dc;
        if (nr < 0 || nr >= SIZE || nc < 0 || nc >= SIZE) continue;
        const nk = `${nr},${nc}`;
        if (cellSet.has(nk) || checked.has(nk)) continue;
        checked.add(nk);
        // Only grow into cells not occupied by any other piece
        const occupied = tableGrid[nr][nc].some(id => id !== t.id);
        if (!occupied) growable.push(nk);
      }
    }
    if (!growable.length) continue;

    // ── Swap: remove one, grow one ────────────────────────────────────────
    const removeKey = removable[Math.floor(Math.random() * removable.length)];
    const growKey   = growable[Math.floor(Math.random() * growable.length)];

    const [rr, rc] = removeKey.split(",").map(Number);
    const [gr, gc] = growKey.split(",").map(Number);

    // Update tableGrid immediately so the next step sees accurate occupancy
    tableGrid[rr][rc] = tableGrid[rr][rc].filter(id => id !== t.id);
    if (tableGrid[rr][rc].length === 0) resetCell(rr, rc);
    if (!tableGrid[gr][gc].includes(t.id)) tableGrid[gr][gc].push(t.id);

    // Update t.cells
    t.cells = t.cells.filter(({r,c}) => !(r === rr && c === rc));
    t.cells.push({ r: gr, c: gc });
  }

  // Re-render once after all steps
  const bb = rugBBox(t.cells);
  t.rMin = bb.rMin; t.rMax = bb.rMax; t.cMin = bb.cMin; t.cMax = bb.cMax;
  renderRugEl(t);
  // Reset conflict timer — shape changed so position relationship may have changed
  delete t.conflictSince;
}

function randomSquiggleAll() {
  if (gameOver) return;
  for (const t of tables) {
    if (t.type === "rug") squiggleRug(t);
  }
}

